import{_ as o,l as i,o as e,c as m,v as l,p,x as r,d,i as s,S as n}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"TP 通信重叠","description":"","frontmatter":{"title":"TP 通信重叠","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/tp-comm-overlap.md","filePath":"llm/tp-comm-overlap.md","lastUpdated":1789023840000}'),c={name:"llm/tp-comm-overlap.md"};function A(h,a,_,E,T,u){const t=i("Mermaid");return e(),m("div",null,[a[1]||(a[1]=l('<h1 id="tp-通信重叠" tabindex="-1">TP 通信重叠 <a class="header-anchor" href="#tp-通信重叠" aria-label="Permalink to &quot;TP 通信重叠&quot;">​</a></h1><div class="epigraph"><p>层内 All-Reduce 与下一层的 GEMM 在数据依赖上不是铁板一块：切对流水，通信可以躲进计算的阴影里。</p><footer>—— Shoeybi 等 Megatron-LM 的切分使非线性局部化；推理引擎把短 AR 与下一层投影重叠</footer></div><p><a href="/llm/custom-allreduce">上一课</a>把短 All-Reduce 的路径选好。本课问墙钟能不能 <em>藏</em> 掉它。训练里通信重叠是老问题；decode 每层计算很瘦，阴影浅，重叠更难、也更值钱。依赖链是：行并行 GEMM 产出部分和 → AR → 下一层需要完整向量。若下一层能先做不依赖完整向量的工作（比如已经列切、只需要本地 KV 的注意力），就可以错开。切错则 AR 成为硬屏障。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>逐步时间 \\(\\approx T_{\\mathrm{cmp}}+T_{\\mathrm{comm}}\\) 若串行。重叠后 \\(\\approx \\max(T_{\\mathrm{cmp}},T_{\\mathrm{comm}})+\\) 无法隐藏的暴露通信。decode 上 \\(T_{\\mathrm{cmp}}\\) 小，能藏的通信有限；prefill 上 \\(T_{\\mathrm{cmp}}\\) 大，AR 更容易藏。缺口是按阶段决定要不要为重叠改切分与流（CUDA stream），而不是处处套训练的 overlap 模板。</p><p>投机校验让一层的查询变宽，\\(T_{\\mathrm{cmp}}\\) 上升，重叠窗口变大——加速比不只来自少步，也来自更好藏通信。</p><p><span class="marginnote">暴露通信是无法与任何本地计算并行的那一段：依赖尚未满足。流水图画错会把「已重叠」写进文档，profiler 上 NCCL/自定义 AR 仍与 GEMM 串行。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>注意力：头在本地，softmax 不通信；输出投影行并行后 AR。MLP：列切上投影本地非线性，下投影后 AR。重叠点：上一层 AR 与下一层 QKV 或上投影的本地部分。实现用双流：计算流与通信流，事件同步。CUDA Graph 要包含两流，否则捕获后重叠消失。自定义 AR 的持久工作组必须能在通信流上跑。</p><p>测：Nsight 上看 AR 与 GEMM 的时间条是否交叠。只看逐步毫秒会把重叠与更快的 AR 混在一起。</p>',10)),(e(),p(n,null,{default:r(()=>[s(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEMM1%5B%22%E8%A1%8C%E5%B9%B6%E8%A1%8C%20GEMM%22%5D%20--%3E%20AR%5B%22All-Reduce%22%5D%0A%20%20GEMM1%20--%3E%20LOC%5B%22%E4%B8%8B%E4%B8%80%E5%B1%82%E6%9C%AC%E5%9C%B0%E5%8F%AF%E5%81%9A%E9%83%A8%E5%88%86%22%5D%0A%20%20AR%20--%3E%20BAR%5B%22%E9%9C%80%E8%A6%81%E5%AE%8C%E6%95%B4%E5%90%91%E9%87%8F%E7%9A%84%E9%83%A8%E5%88%86%22%5D%0A%20%20LOC%20--%3E%20BAR%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>数学依赖不能违背：残差加若需要完整 \\(Y\\)，AR 之后才能加。有的实现把残差放进融合核，通信必须先完成。为重叠而拆融合，可能得不偿失——decode 上融合省的 HBM 可能大于重叠省的暴露通信。应用 profiler 决定，不要按训练论文的百分比抄。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>跨节点 TP 的 AR 更长，更值得重叠，但也更难与自定义路径结合。MoE 的 all-to-all 是另一类通信，不要与稠密 TP 的 AR 重叠策略混写。下一课：还在用 NCCL 时，有哪些旋钮。</p><p>出处：Megatron-LM；NVIDIA 对 Transformer 引擎通信重叠的工程说明。不发明 arXiv。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>重叠把逐步时间从和变成近似 max；decode 阴影浅。</li><li>切分必须留下「AR 未完成也能做」的本地工作。</li><li>双流 + 事件；CUDA Graph 要含通信流。</li><li>拆融合换重叠未必赢，用 trace 决定。</li><li>prefill / 投机宽查询更好藏。</li><li>下一课：NCCL 调优。</li><li>出处：Shoeybi et al., Megatron-LM。</li></ul>',7))])}const M=o(c,[["render",A]]);export{C as __pageData,M as default};
